  'Admission enquiry assistant': 'ভর্তি তথ্য সহকারী',
  'An AI assistant that answers only from this school’s published admission information. For anything else, leave your contact details and the admissions office will call you.': 'একটি AI সহকারী যা শুধু এই স্কুলের প্রকাশিত ভর্তি তথ্য থেকে উত্তর দেয়। অন্য যেকোনো বিষয়ে আপনার যোগাযোগের তথ্য দিন, ভর্তি অফিস আপনাকে ফোন করবে।',
  'Ask about admission dates, documents, fees or which class suits your child’s age.': 'ভর্তির তারিখ, প্রয়োজনীয় কাগজপত্র, ফি বা আপনার সন্তানের বয়স অনুযায়ী কোন শ্রেণি উপযুক্ত — এসব বিষয়ে জিজ্ঞেস করুন।',
