  'Creates one draft comment per exam result. Approving a draft writes it into that result’s remarks.': 'প্রতিটি পরীক্ষার ফলাফলের জন্য একটি করে খসড়া মন্তব্য তৈরি করে। খসড়া অনুমোদন করলে তা সংশ্লিষ্ট ফলাফলের মন্তব্যে যুক্ত হয়।',
