  'Also draft for results that already have remarks': 'যেসব ফলাফলে আগেই মন্তব্য আছে সেগুলোর জন্যও খসড়া তৈরি করুন',
  'Could not generate drafts.': 'খসড়া তৈরি করা যায়নি।',
  'Insights computed from your school’s own records, with optional AI-written summaries and drafts. Anything for guardians or students is reviewed by staff first.': 'আপনার স্কুলের নিজস্ব রেকর্ড থেকে তৈরি ইনসাইট, সাথে ঐচ্ছিক AI-লিখিত সারাংশ ও খসড়া। অভিভাবক বা শিক্ষার্থীর জন্য যেকোনো কিছু আগে কর্মীরা পর্যালোচনা করেন।',
  'AI features': 'AI ফিচার',
