  'Demo mode': 'ডেমো মোড',
  'The AI provider could not be used for this request, so template text built from your school’s real data is shown.': 'এই অনুরোধে AI প্রোভাইডার ব্যবহার করা যায়নি, তাই আপনার স্কুলের প্রকৃত ডেটা থেকে তৈরি টেমপ্লেট টেক্সট দেখানো হচ্ছে।',
  'AI API key not configured — this text is a template built from your school’s real data; no AI model was called and nothing was sent.': 'AI API কি কনফিগার করা নেই — এই টেক্সটটি আপনার স্কুলের প্রকৃত ডেটা থেকে তৈরি একটি টেমপ্লেট; কোনো AI মডেল ব্যবহার করা হয়নি এবং কিছুই পাঠানো হয়নি।',
  'No AI API key is configured. Summaries and drafts use templates built from your school’s real data; no AI model is called and nothing is sent.': 'কোনো AI API কি কনফিগার করা নেই। সারাংশ ও খসড়া আপনার স্কুলের প্রকৃত ডেটা থেকে তৈরি টেমপ্লেট ব্যবহার করে; কোনো AI মডেল ব্যবহার করা হয় না এবং কিছুই পাঠানো হয় না।',
  'AI enabled': 'AI চালু আছে',
  'Generated text comes from {provider} ({model}). All numbers are computed from your school’s records; review AI text before sharing.': 'তৈরিকৃত টেক্সট {provider} ({model}) থেকে আসে। সব সংখ্যা আপনার স্কুলের রেকর্ড থেকে হিসাব করা; শেয়ার করার আগে AI টেক্সট যাচাই করুন।',
  'Claude is temporarily unavailable; Gemini is being used.': 'Claude সাময়িকভাবে অনুপলব্ধ; Gemini ব্যবহার করা হচ্ছে।',
