  'Some transactions were made in demo mode (gateway API key not configured). They were simulated and no money was charged, but they did mark invoices as paid.': 'কিছু লেনদেন ডেমো মোডে হয়েছে (গেটওয়ের API কি কনফিগার করা নেই)। এগুলো সিমুলেটেড ছিল এবং কোনো টাকা কাটা হয়নি, তবে এগুলো ইনভয়েসকে পরিশোধিত হিসেবে চিহ্নিত করেছে।',
