  'Could not load this student\'s concessions — the server still applies them when the invoice is created.': 'এই শিক্ষার্থীর ছাড় লোড করা যায়নি — ইনভয়েস তৈরির সময় সার্ভার তবুও সেগুলো প্রয়োগ করবে।',
  'No active concessions for this student.': 'এই শিক্ষার্থীর কোনো সক্রিয় ছাড় নেই।',
