  'Changing the type does not convert values already saved; invalid ones must be corrected on next edit.': 'ধরন পরিবর্তন করলে আগে সংরক্ষিত মানগুলো রূপান্তরিত হয় না; অবৈধ মানগুলো পরবর্তী সম্পাদনার সময় সংশোধন করতে হবে।',
  'Options (one per line)': 'অপশন (প্রতি লাইনে একটি)',
