  'New field': 'নতুন ফিল্ড',
  'How custom fields work': 'কাস্টম ফিল্ড যেভাবে কাজ করে',
  'Values are checked against the field type on every save. Marking a field required applies to new admissions and to any edit of a student’s custom fields.': 'প্রতিবার সংরক্ষণের সময় মানগুলো ফিল্ডের ধরন অনুযায়ী যাচাই করা হয়। কোনো ফিল্ড আবশ্যক করলে তা নতুন ভর্তি এবং শিক্ষার্থীর কাস্টম ফিল্ডের যেকোনো সম্পাদনায় প্রযোজ্য হয়।',
