  'Open the help centre': 'সহায়তা কেন্দ্র খুলুন',
  'Integrations, support and offline attendance': 'ইন্টিগ্রেশন, সাপোর্ট ও অফলাইন উপস্থিতি',
  'Connect other systems, talk to the PeopleNIT team from inside the app, export all your data, and keep marking attendance without internet.': 'অন্য সিস্টেম যুক্ত করুন, অ্যাপের ভেতর থেকেই PeopleNIT টিমের সঙ্গে কথা বলুন, আপনার সব ডেটা এক্সপোর্ট করুন এবং ইন্টারনেট ছাড়াই উপস্থিতি নিতে থাকুন।',
  'Bangla for all new pages': 'সব নতুন পেজে বাংলা',
