  'Plans, branches, devices and setup checklist': 'প্ল্যান, শাখা, ডিভাইস ও সেটআপ চেকলিস্ট',
  'Institution-wide settings and tools for running more than one campus.': 'একাধিক ক্যাম্পাস পরিচালনার জন্য প্রতিষ্ঠানব্যাপী সেটিংস ও টুল।',
  'Analytics and scheduled reports': 'অ্যানালিটিক্স ও নির্ধারিত রিপোর্ট',
  'Finance, attendance and academic analytics, filtered to what your role may see.': 'আর্থিক, উপস্থিতি ও একাডেমিক অ্যানালিটিক্স, আপনার ভূমিকা অনুযায়ী যা দেখার অনুমতি আছে তা-ই।',
  'Inventory, library fines and transport stops': 'ইনভেন্টরি, লাইব্রেরি জরিমানা ও পরিবহন স্টপ',
  'Track school assets and stock, charge library fines automatically, and bill transport monthly.': 'স্কুলের সম্পদ ও মজুত ট্র্যাক করুন, লাইব্রেরির জরিমানা স্বয়ংক্রিয়ভাবে ধার্য করুন এবং পরিবহনের মাসিক বিল করুন।',
  'Staff and subject attendance, QR check-in, payroll': 'কর্মী ও বিষয়ভিত্তিক উপস্থিতি, কিউআর চেক-ইন, বেতন',
  'More ways to take attendance, and payroll with allowances and deductions.': 'উপস্থিতি নেওয়ার আরও উপায়, এবং ভাতা ও কর্তনসহ বেতন ব্যবস্থাপনা।',
  'AI you can review before it is sent': 'পাঠানোর আগে পর্যালোচনাযোগ্য AI',
  'All AI text meant for guardians or students waits in a review queue for staff approval.': 'অভিভাবক বা শিক্ষার্থীদের জন্য তৈরি সব AI টেক্সট কর্মীদের অনুমোদনের জন্য পর্যালোচনা সারিতে অপেক্ষা করে।',
  'Grading scales, promotion and transcripts': 'গ্রেডিং স্কেল, প্রমোশন ও ট্রান্সক্রিপ্ট',
  'Set your own grading, promote a whole class at once, and print transcripts.': 'নিজস্ব গ্রেডিং নির্ধারণ করুন, একবারে পুরো শ্রেণি প্রমোশন দিন এবং ট্রান্সক্রিপ্ট প্রিন্ট করুন।',
  'Campaigns, admissions CRM and targeted notices': 'ক্যাম্পেইন, ভর্তি CRM ও নির্দিষ্ট লক্ষ্যভিত্তিক নোটিশ',
  'Reach the right people and follow up every admission enquiry.': 'সঠিক মানুষের কাছে পৌঁছান এবং প্রতিটি ভর্তি অনুসন্ধানের ফলো-আপ করুন।',
  'Online fee payments and receipts': 'অনলাইনে ফি পরিশোধ ও রসিদ',
  'Guardians can pay with bKash, Nagad or card; every payment gets a receipt number.': 'অভিভাবকেরা বিকাশ, নগদ বা কার্ডে পরিশোধ করতে পারেন; প্রতিটি পেমেন্টে একটি রসিদ নম্বর থাকে।',
  'Every screen redesigned': 'প্রতিটি স্ক্রিন নতুনভাবে ডিজাইন',
  'A consistent, mobile-friendly look across the whole app.': 'পুরো অ্যাপজুড়ে একই রকম, মোবাইল-বান্ধব চেহারা।',
  'Security fixes, dashboards and the student profile': 'নিরাপত্তা সংশোধন, ড্যাশবোর্ড ও শিক্ষার্থী প্রোফাইল',
  'Role dashboards, a full student profile, and several security fixes.': 'ভূমিকাভিত্তিক ড্যাশবোর্ড, পূর্ণাঙ্গ শিক্ষার্থী প্রোফাইল এবং বেশ কিছু নিরাপত্তা সংশোধন।',
  'New look, dark mode and Bangla': 'নতুন চেহারা, ডার্ক মোড ও বাংলা',
  'Brand colours, a component library, light/dark themes and an English/Bangla switch.': 'ব্র্যান্ডের রং, কম্পোনেন্ট লাইব্রেরি, লাইট/ডার্ক থিম এবং ইংরেজি/বাংলা পরিবর্তনের সুবিধা।',
  'Leave management and safer sign-in': 'ছুটি ব্যবস্থাপনা ও আরও নিরাপদ সাইন-ইন',
  'Staff and student leave requests, and sign-in with phone or email plus two-step verification.': 'কর্মী ও শিক্ষার্থীদের ছুটির আবেদন, এবং ফোন বা ইমেইল দিয়ে দুই-ধাপের যাচাইসহ সাইন-ইন।',
  'New admission form, online registrations and teachers': 'নতুন ভর্তি ফর্ম, অনলাইন নিবন্ধন ও শিক্ষক',
  'A rebuilt student admission form, online registration approvals and teacher management.': 'নতুনভাবে তৈরি শিক্ষার্থী ভর্তি ফর্ম, অনলাইন নিবন্ধন অনুমোদন এবং শিক্ষক ব্যবস্থাপনা।',
  'Institution sign-up controls': 'প্রতিষ্ঠান নিবন্ধনের নিয়ন্ত্রণ',
  'Platform-side controls for which schools can apply.': 'কোন স্কুল আবেদন করতে পারবে তার প্ল্যাটফর্ম-পর্যায়ের নিয়ন্ত্রণ।',
